mapper.select:
SELECT tc.department_Id AS departmentId, any_value(tc.department_name) AS departmentName, COUNT(1) AS groupCount FROM tb_create_group tc left join tb_group_extends tg on tg.group_id = tc.group_id
tg.group_type = 2
and tc.department_Id IN
#{code}
and tc.create_time >= #{startTime}
and tc.create_time <= CONCAT(#{endTime}, ' 23:59:59')
and tc.source = #{source}
GROUP BY tc.department_Id ORDER BY groupCount DESC;

SELECT COUNT(1) FROM tb_create_group


        and department_Id IN

            #{code}



        and create_time >= #{startTime}


        and create_time <= CONCAT(#{endTime}, ' 23:59:59')


        and source = #{source}

WITH dept_latest AS ( SELECT department_id, department_name FROM ( SELECT department_id,department_name,create_time, ROW_NUMBER() OVER (PARTITION BY department_id ORDER BY create_time DESC) AS rn FROM tb_create_group tc where 1 = 1
) t WHERE rn = 1 ) SELECT tc.owner_id AS userId, tc.owner_name AS userName, ld.department_name AS departmentName, COUNT(1) AS totalCount FROM tb_create_group tc left join tb_group_extends tg on tg.group_id = tc.group_id left join dept_latest ld on tc.department_id = ld.department_id
tg.group_type = 2
GROUP BY tc.owner_id, tc.owner_name, tc.department_id, ld.department_name ORDER BY totalCount DESC;

SELECT cg.group_id, cg.update_time, cg.owner_id, cg.owner_name, cg.department_id, cg.department_name, cg.create_time, cg.group_name, cg.source, ge.group_type FROM tb_create_group cg LEFT JOIN tb_group_extends ge ON ge.group_id = cg.group_id
AND (cg.update_time, cg.group_id) > (#{timeAfter}, #{idAfter})
ORDER BY cg.update_time ASC, cg.group_id ASC LIMIT #{pageSize}
